package br.com.onda;
import android.content.*;
import android.net.Uri;
import android.provider.DocumentsContract;
import androidx.media3.common.MediaItem;
import java.io.*;
import java.util.*;
import org.junit.*;
import static org.junit.Assert.*;
import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;

@androidx.media3.common.util.UnstableApi
public class FavoriteCopiesTest {
 Context c;String history;Map<String,?> folders;Set<String> favorites;String prefix;final List<File> sources=new ArrayList<>();
 @Before public void before()throws Exception{c=getInstrumentation().getTargetContext();history=c.getSharedPreferences(DownloadHistory.PREF,0).getString("data",null);folders=c.getSharedPreferences(OndaFolders.PREF,0).getAll();favorites=new HashSet<>(c.getSharedPreferences("library",0).getStringSet("favorites",Collections.emptySet()));prefix="Favorite-native-"+UUID.randomUUID();Uri tree=null;for(UriPermission p:c.getContentResolver().getPersistedUriPermissions())if(p.isWritePermission()&&DocumentsContract.isTreeUri(p.getUri())){tree=p.getUri();break;}assertNotNull(tree);OndaFolders.configure(c,tree);}
 @After public void after(){c.stopService(new Intent(c,MediaDownloadService.class));for(DownloadHistory.Entry entry:DownloadHistory.read(c))if(entry.title.startsWith(prefix)&&!entry.uri.isEmpty())try{DocumentsContract.deleteDocument(c.getContentResolver(),Uri.parse(entry.uri));}catch(Exception ignored){}for(File f:sources)f.delete();SharedPreferences.Editor h=c.getSharedPreferences(DownloadHistory.PREF,0).edit();if(history==null)h.remove("data");else h.putString("data",history);h.commit();SharedPreferences.Editor folder=c.getSharedPreferences(OndaFolders.PREF,0).edit().clear();for(Map.Entry<String,?> e:folders.entrySet())if(e.getValue() instanceof String)folder.putString(e.getKey(),(String)e.getValue());else if(e.getValue() instanceof Boolean)folder.putBoolean(e.getKey(),(Boolean)e.getValue());folder.commit();c.getSharedPreferences("library",0).edit().putStringSet("favorites",favorites).commit();}
 File fixture(String asset)throws Exception{File f=File.createTempFile("favorite-source-","."+asset.substring(asset.lastIndexOf('.')+1),c.getCacheDir());sources.add(f);try(InputStream in=getInstrumentation().getContext().getAssets().open(asset);OutputStream out=new FileOutputStream(f)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}return f;}
 byte[] bytes(Uri uri)throws Exception{try(InputStream in=c.getContentResolver().openInputStream(uri)){assertNotNull(in);ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
 void run(List<MediaItem> items)throws Exception{String request=FavoriteCopies.prepare(c,items);c.getSharedPreferences("downloads",0).edit().putString("status","").commit();getInstrumentation().runOnMainSync(()->c.startForegroundService(new Intent(c,MediaDownloadService.class).putExtra("favorite_copies",request)));long end=System.currentTimeMillis()+90000;String status="";while(System.currentTimeMillis()<end){status=c.getSharedPreferences("downloads",0).getString("status","");if(!MediaDownloadService.activeDownload&&(status.startsWith("Favoritas:")||status.startsWith("Operação interrompida")))break;Thread.sleep(100);}assertTrue(status,status.startsWith("Favoritas:"));assertFalse(new File(c.getCacheDir(),request).exists());}
 MediaItem item(File f,String name){return new MediaItem.Builder().setMediaId(name).setUri(Uri.fromFile(f)).setMediaMetadata(new androidx.media3.common.MediaMetadata.Builder().setTitle(name).build()).build();}
 @Test public void actualServiceCopiesFormatsAndPreservesSourcesAndFavorites()throws Exception{File a=fixture("audio.m4a"),b=fixture("speech.wav");Set<String> selected=new HashSet<>(Arrays.asList(prefix+"-a",prefix+"-b"));c.getSharedPreferences("library",0).edit().putStringSet("favorites",selected).commit();run(Arrays.asList(item(a,prefix+"-a"),item(b,prefix+"-b")));int count=0;for(DownloadHistory.Entry e:DownloadHistory.read(c))if(e.title.startsWith(prefix)){assertEquals("done",e.state);File original=e.title.endsWith("-a")?a:b;assertArrayEquals(java.nio.file.Files.readAllBytes(original.toPath()),bytes(Uri.parse(e.uri)));assertTrue(original.exists());count++;}assertEquals(2,count);assertEquals(selected,c.getSharedPreferences("library",0).getStringSet("favorites",Collections.emptySet()));}
 @Test public void unavailableFavoriteRecordsFailureAndRemovesIncompleteOutput()throws Exception{File missing=new File(c.getCacheDir(),prefix+".m4a");run(Collections.singletonList(item(missing,prefix+"-missing")));DownloadHistory.Entry entry=DownloadHistory.read(c).stream().filter(e->e.title.startsWith(prefix)).findFirst().orElseThrow(AssertionError::new);assertEquals("failed",entry.state);assertTrue(entry.uri.isEmpty());Uri directory=OndaFolders.directory(c,"mp3");try(android.database.Cursor cursor=c.getContentResolver().query(DocumentsContract.buildChildDocumentsUriUsingTree(directory,DocumentsContract.getDocumentId(directory)),new String[]{DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null)){while(cursor!=null&&cursor.moveToNext())assertFalse(cursor.getString(0).startsWith(prefix));}}
}
